package render

import (
	"fmt"
	"strings"

	"github.com/hayone1/gitopsify/pkg/model"
)

const applyScriptHead = `#!/usr/bin/env bash
# Generated by gitopsify. Applies the %[1]s environment in reconciliation order:
# manifests with kubectl server-side apply, Helm releases with helm upgrade
# --install. Platform apps (CRDs, operators, webhooks) are waited for before the
# apps that need them.
#
#   ./apply-%[1]s.sh [--context NAME] [--kubeconfig FILE] [--dry-run] [kubectl flags...]
#
# Needs kubectl (or kustomize) and, for Helm apps, helm 3 or 4.
set -euo pipefail
cd "$(dirname "$0")"

kubectl_args=()
helm_args=()
dry_run=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --context) kubectl_args+=(--context "$2"); helm_args+=(--kube-context "$2"); shift 2 ;;
    --context=*) kubectl_args+=("$1"); helm_args+=(--kube-context "${1#*=}"); shift ;;
    --kubeconfig) kubectl_args+=(--kubeconfig "$2"); helm_args+=(--kubeconfig "$2"); shift 2 ;;
    --kubeconfig=*) kubectl_args+=("$1"); helm_args+=("$1"); shift ;;
    --dry-run) dry_run=1; shift ;;
    *) kubectl_args+=("$1"); shift ;;
  esac
done

k() { kubectl ${kubectl_args[@]+"${kubectl_args[@]}"} "$@"; }
h() { helm ${helm_args[@]+"${helm_args[@]}"} "$@"; }

build() {
  if command -v kustomize >/dev/null 2>&1; then
    kustomize build "$1"
  else
    kubectl kustomize "$1"
  fi
}

# apply DIR: builds a Kustomization and server-side applies it.
apply() {
  echo ">> $1"
  build "$1" | k apply --server-side --field-manager=gitopsify --force-conflicts ${dry_run:+--dry-run=server} -f -
}

# apply_helm DIR RELEASE NAMESPACE CHART [helm flags...]: installs or upgrades
# a release with the values in DIR.
apply_helm() {
  local dir=$1 release=$2 namespace=$3 chart=$4
  shift 4
  echo ">> ${dir} (Helm release ${namespace}/${release})"
  h upgrade --install "${release}" "${chart}" --namespace "${namespace}" --create-namespace \
    -f "${dir}/values.yaml" ${dry_run:+--dry-run=server} "$@"
}

# wait_crds and wait_available let CRDs and the Deployments of operators and
# webhooks become ready before the apps that use them.
wait_crds() {
  [[ -n "${dry_run}" ]] || k wait --for=condition=Established crd --all --timeout=120s
}

wait_available() {
  [[ -n "${dry_run}" ]] || k wait --for=condition=Available deployment --all -n "$1" --timeout=300s
}
`

// renderPlain writes, per environment, a script that applies every app in
// reconciliation order. It is for people wiring the manifests into their own
// tooling, and for a first manual rollout.
func (r *renderer) renderPlain(l layout) error {
	for _, env := range l.envs {
		var b strings.Builder
		fmt.Fprintf(&b, applyScriptHead, env.Name)
		wave := 0
		first := true
		for _, a := range r.appsByWave() {
			if first || a.Wave != wave {
				fmt.Fprintf(&b, "\n# wave %d\n", a.Wave)
				wave, first = a.Wave, false
			}
			dir := l.appEnv(a.Name, env.Name)
			platform := a.Phase == model.PhasePlatform
			if a.IsHelm() {
				args := []string{"apply_helm", dir, a.Release.Name, a.Release.Namespace}
				args = append(args, r.helmChartArgs(l, a)...)
				if platform {
					args = append(args, "--wait", "--timeout", "10m")
				}
				b.WriteString(shellJoin(args) + "\n")
			} else {
				b.WriteString(shellJoin([]string{"apply", dir}) + "\n")
				if platform && a.Namespace != "" {
					b.WriteString(shellJoin([]string{"wait_available", a.Namespace}) + "\n")
				}
			}
			if a.Phase == model.PhaseCRDs || platform && hasCRDs(a) {
				b.WriteString("wait_crds\n")
			}
		}
		r.tree.Add(l.file("apply-"+env.Name+".sh"), []byte(b.String()))
	}
	return nil
}

// helmChartArgs returns the chart argument and flags of helm upgrade for an
// app: a vendored chart directory, an OCI reference or a repository chart.
func (r *renderer) helmChartArgs(l layout, a *model.App) []string {
	c := r.chartRef(l, a)
	switch {
	case c.vendored:
		return []string{"./" + c.chartPath}
	case c.oci:
		return []string{strings.TrimSuffix(c.repoURL, "/") + "/" + c.chart, "--version", c.version}
	}
	return []string{c.chart, "--repo", c.repoURL, "--version", c.version}
}

func hasCRDs(a *model.App) bool {
	if a.Release != nil && len(a.Release.CRDs) > 0 {
		return true
	}
	for _, o := range a.Objects {
		if o.IsCRD() {
			return true
		}
	}
	return false
}

// shellJoin quotes words for bash when they need it.
func shellJoin(words []string) string {
	out := make([]string, len(words))
	for i, w := range words {
		if w != "" && strings.Trim(w, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_./:=@+,") == "" {
			out[i] = w
		} else {
			out[i] = "'" + strings.ReplaceAll(w, "'", `'\''`) + "'"
		}
	}
	return strings.Join(out, " ")
}
